import json, os, sys, time, tempfile, hashlib, platform, resource, subprocess, datetime
t0 = time.monotonic(); ROOT = '/home/ryan/rule30-lab'
resource.setrlimit(resource.RLIMIT_AS, (1073741824, 1073741824))
FORB = ('uu', 'ttttt', 'ututtu')
def adm(w):
    for f in FORB:
        if f in w: return False
    return True
bylen = {0: ['']}
for L in range(1, 24):
    cur = []
    for w in bylen[L-1]:
        for ch in ['t', 'u']:
            if adm(w + ch): cur.append(w + ch)
    bylen[L] = cur
for L in (20, 21, 23):
    for w in bylen[L]:
        us = [i for i, ch in enumerate(w) if ch == 'u']
        for a, b in zip(us, us[1:]): assert 2 <= b - a <= 5
for k, L in ((2, 20), (3, 21), (5, 23)):
    n = k - 2; worst = -1
    for w in bylen[L]:
        cands = [c for c in range(n, n+5) if w[c] == 'u']
        assert cands
        c = cands[0]
        us = [i for i, ch in enumerate(w) if ch == 'u']
        j = us.index(c)
        assert j + 3 < len(us)
        B = us[j+3] - c
        assert c + B + 1 <= k + 18
        if c + B + 1 > worst: worst = c + B + 1
    assert worst == k + 18, (k, worst)
ex = 'tttt' + 'utttt'*3 + 'u'
assert len(ex) == 20 and adm(ex)
cpu = next((l.split(':',1)[1].strip() for l in open('/proc/cpuinfo').read().splitlines() if l.startswith('model name')), 'unknown')
src = open(__file__).read()
summary = {'forbidden': list(FORB), 'lengths': [20, 21, 23], 'counts': {L: len(bylen[L]) for L in (20, 21, 23)}, 'gap_range_ok': True, 'extremal': ex, 'max_need_equals_k_plus_18': True}
rec = {'experiment_id': '20260905_boundary_length_lemma_combinatorics', 'timestamp_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'git_commit': subprocess.check_output(['git','rev-parse','HEAD'], cwd=ROOT, text=True).strip(), 'question': 'problem1', 'hypothesis': 'Worst-case four-observed-u structure needs exactly k+18 (ttttu-repeat attains it); occurrence threshold needs only admissible-appended final u and may be smaller.', 'backend': 'python-exact-enumeration', 'parameters': {'lengths': [20, 21, 23], 'k_values': [2, 3, 5], 'wall_limit_seconds': 120, 'address_space_bytes': 1073741824}, 'hardware': {'cpu_model': cpu, 'machine': platform.machine(), 'cpu_count': os.cpu_count(), 'peak_rss_kib': resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}, 'software': {'python': sys.version, 'platform': platform.platform()}, 'runtime_seconds': time.monotonic()-t0, 'result_hashes': {'source_sha256': hashlib.sha256(src.encode()).hexdigest(), 'result_sha256': hashlib.sha256(json.dumps(summary, sort_keys=True, separators=(',', ':')).encode()).hexdigest()}, 'source_text': src, 'result_summary': summary, 'interpretation': 'Gap range and worst-case arithmetic confirmed.', 'status': 'finite-exhaustive', 'proof_scope': 'Exact enumeration to length 23; translation-invariant argument at k=2,3,5.', 'limitations': ['Shape check only; infinite lemma by hand.', 'k+18 sharpness is for four OBSERVED u only, not the occurrence threshold.']}
fd, tmp = tempfile.mkstemp(dir='/tmp', prefix='rec_', suffix='.tmp')
with os.fdopen(fd,'w') as f: json.dump(rec, f, sort_keys=True, indent=2); f.write(chr(10)); f.flush(); os.fsync(f.fileno())
os.replace(tmp, '/tmp/boundary_lemma_check.json')
print('R3 lemma pass')
